#!/usr/bin/env bash
set -euo pipefail
if [[ "${ALLOW_LAB_DEPLOYMENT:-}" != "yes" ]]; then
  echo "Deployment deferred. Set ALLOW_LAB_DEPLOYMENT=yes only in an authorized funded lab session." >&2
  exit 2
fi
: "${ARTIFACT_BUCKET:?Specify the private S3 bucket}"
: "${API_TOKEN:?Set a random local access token}"
command -v docker >/dev/null
command -v aws >/dev/null
mkdir -p artifacts/uci
aws s3 sync "s3://${ARTIFACT_BUCKET}/uci/" artifacts/uci/ --only-show-errors
# Download only artifacts generated by this project and uploaded by the authorized owner.
# Never load an arbitrary internet pickle/joblib file.
docker compose up -d --build
